import math

def sin_series(r, terms):
    return sum((-1)**k * r**(2*k + 1) / math.factorial(2*k + 1) for k in range(terms))

def cos_series(r, terms):
    return sum((-1)**k * r**(2*k) / math.factorial(2*k) for k in range(terms))

def my_sin(x):
    print(f"sin({x})")
    k = round(x / (2 * math.pi))
    r = x - 2 * math.pi * k
    print(f"  subtract {k} turns: r = {r:.6f}")
    sign = 1
    if r < 0:
        sign = -1
        r = -r
        print(f"  negative, so sin x = -sin({r:.6f})")
    if r > math.pi / 2:
        r = math.pi - r
        print(f"  over pi/2, so reflect: sin(pi - r) = sin({r:.6f})")
    if r > math.pi / 4:
        value = cos_series(math.pi / 2 - r, 8)
        print(f"  over pi/4, so use cos({math.pi / 2 - r:.6f})")
    else:
        value = sin_series(r, 8)
        print(f"  at most pi/4, so use the sin series at {r:.6f}")
    print(f"  my_sin = {sign * value:.10f}, math.sin = {math.sin(x):.10f}")

my_sin(0.5)
my_sin(2)
my_sin(100)
my_sin(-5)
my_sin(10800)

